begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('70000000-0000-4000-8000-000000000001','portfolio-owner@example.invalid'),('70000000-0000-4000-8000-000000000002','portfolio-other@example.invalid');
delete from private.app_owner;
insert into private.app_owner(user_id,github_user_id) values('70000000-0000-4000-8000-000000000001','10001');
create temp table portfolio_fixture(doc jsonb);
insert into portfolio_fixture values('__DOCUMENT__'::jsonb);
grant select on portfolio_fixture to authenticated;
select ok(not has_table_privilege('anon','public.portfolio_sites','select'),'anon cannot read draft table');
select ok(not has_table_privilege('anon','public.portfolio_versions','select'),'anon cannot read history');
select ok(not has_function_privilege('anon','public.save_portfolio(jsonb,integer)','execute'),'anon cannot save');
select ok(not has_function_privilege('anon','public.publish_portfolio(integer,uuid)','execute'),'anon cannot publish');
select ok(not has_table_privilege('authenticated','public.portfolio_versions','update'),'versions immutable');
select ok(not has_table_privilege('authenticated','public.portfolio_sites','update'),'direct pointer mutation blocked');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.save_portfolio((select doc from portfolio_fixture),0)$$,'42501',null,'non-owner RPC denied');
select is((select count(*)::int from public.portfolio_sites),0,'non-owner sees no drafts');
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.save_portfolio((select doc from portfolio_fixture),0)$$,'owner bootstraps draft');
select throws_ok($$select public.save_portfolio((select doc from portfolio_fixture),0)$$,'P0001','conflict','repeat bootstrap cannot overwrite');
select throws_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,navbar,0,href}','"javascript:alert(1)"'),1)$$,'23514','invalid_document','direct RPC rejects unsafe URL');
select throws_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,avatarUrl}','"https://evil.invalid/avatar.svg"'),1)$$,'23514','invalid_document','direct RPC rejects arbitrary image');
select throws_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,skills,1,id}','"skill-0"'),1)$$,'23514','invalid_document','direct RPC rejects duplicate IDs');
select throws_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,skills,1,id}','"different"'),1)$$,'23514','invalid_document','direct RPC rejects locale ID mismatch');
select throws_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,skills,1,icon}','"evil"'),1)$$,'23514','invalid_document','direct RPC rejects unknown icon');
select throws_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,avatarUrl}','"media:80000000-0000-4000-8000-000000000001"'),1)$$,'23514','invalid_document','unregistered media rejected');
select throws_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,navbar,0,href}','"https://user:pass@evil.invalid"'),1)$$,'23514','invalid_document','DB rejects URL credentials');
select throws_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,contact,social}','[]'),1)$$,'23514','invalid_document','DB rejects empty required socials');
select throws_ok($$select public.save_portfolio((select doc from portfolio_fixture),99)$$,'P0001','conflict','stale save blocked');
select throws_ok($$insert into public.portfolio_sites(draft) values('{}')$$,'42501',null,'direct table insert denied');
select lives_ok($$select public.publish_portfolio(1)$$,'publish succeeds');
select is((select revision from public.portfolio_sites),2,'publish bumps CAS revision');
select throws_ok($$select public.publish_portfolio(1)$$,'P0001','conflict','stale publish blocked');
select lives_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,name}','"PRIVATE DRAFT"'),2)$$,'save later draft');
select is((select document#>>'{locales,vi,name}' from public.read_published_portfolio()),'Vo Dinh Quan','current snapshot isolated from draft edits');
select lives_ok($$select public.publish_portfolio(3,(select id from public.portfolio_versions order by created_at limit 1))$$,'restore republishes retained snapshot');
select is((select count(*)::int from public.portfolio_versions),2,'restore creates immutable new version');
insert into public.portfolio_media(id,path,mime,bytes) values
('80000000-0000-4000-8000-000000000001',auth.uid()::text || '/portfolio/80000000-0000-4000-8000-000000000001.webp','image/webp',10),
('80000000-0000-4000-8000-000000000002',auth.uid()::text || '/portfolio/80000000-0000-4000-8000-000000000002.webp','image/webp',10);
select lives_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,avatarUrl}','"media:80000000-0000-4000-8000-000000000001"'),4)$$,'attach registered media');
select lives_ok($$select public.publish_portfolio(5)$$,'publish media one');
select lives_ok($$select public.save_portfolio(jsonb_set((select doc from portfolio_fixture),'{locales,vi,avatarUrl}','"media:80000000-0000-4000-8000-000000000002"'),6)$$,'media two remains draft');
select throws_ok($$select public.publish_portfolio(7,'90000000-0000-4000-8000-000000000001')$$,'P0001','missing','invalid restore fails atomically');
select is((select document#>>'{locales,vi,avatarUrl}' from public.read_published_portfolio()),'media:80000000-0000-4000-8000-000000000001','failed publish preserves pointer');
set local role anon;
select is((select count(*)::int from public.read_published_portfolio_media('80000000-0000-4000-8000-000000000001')),1,'current referenced media visible');
select is((select count(*)::int from public.read_published_portfolio_media('80000000-0000-4000-8000-000000000002')),0,'draft-only media hidden');
set local role authenticated;
select lives_ok($$select public.publish_portfolio(7)$$,'publish media two');
set local role anon;
select is((select count(*)::int from public.read_published_portfolio_media('80000000-0000-4000-8000-000000000001')),0,'previous snapshot media hidden');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.portfolio_sites),0,'non-owner cannot see populated draft');
select is((select count(*)::int from public.portfolio_versions),0,'non-owner cannot see populated history');
select is((select count(*)::int from public.portfolio_media),0,'non-owner cannot see private media metadata');
set local role anon;
select is((select count(*)::int from public.read_published_portfolio()),1,'anon reads only one current snapshot');
select throws_ok($$select * from public.portfolio_sites$$,'42501',null,'anon Data API draft denied');
select throws_ok($$select * from public.portfolio_versions$$,'42501',null,'anon Data API history denied');
select is((select count(*)::int from public.read_published_portfolio_media('80000000-0000-4000-8000-000000000099')),0,'unknown/private media invisible');
reset role;
select * from finish();
rollback;
